import React, { useState, useEffect } from "react";
import { db } from "../../firebaseConfig";
import { collection, query, getDocs } from "firebase/firestore";
import { useNavigate } from "react-router-dom";
import "./ExamPage.css";

const ExamPage = ({ studentClass }) => {
  const [subjects, setSubjects] = useState([]);
  const [examData, setExamData] = useState({});
  const [selectedSubject, setSelectedSubject] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchSubjects = async () => {
      setLoading(true);
      try {
        const q = query(collection(db, "exams"));
        const querySnapshot = await getDocs(q);

        const subjectsWithDetails = {};
        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (data.subject && data.examDate && data.examTime) {
            subjectsWithDetails[data.subject] = {
              examDate: data.examDate,
              examTime: data.examTime,
            };
          }
        });

        setSubjects(Object.keys(subjectsWithDetails));
        setExamData(subjectsWithDetails);
      } catch (error) {
        console.error("Error fetching subjects:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchSubjects();
  }, [studentClass]);

  const handleSubjectSelection = (e) => {
    setSelectedSubject(e.target.value);
  };

  const startExam = () => {
    if (selectedSubject) {
      const { examDate, examTime } = examData[selectedSubject];
      const currentDateTime = new Date();
      const examDateTime = new Date(`${examDate}T${examTime}`);

      if (currentDateTime >= examDateTime) {
        navigate(`/exam/${selectedSubject}`);
      } else {
        alert("The exam is not available at this time.");
      }
    } else {
      alert("Please select a subject.");
    }
  };

  return (
    <div className="exam-page">
      <h2>Select an Exam Subject</h2>
      {loading ? (
        <p>Loading subjects...</p>
      ) : (
        <>
          <select
            className="subject-dropdown"
            value={selectedSubject}
            onChange={handleSubjectSelection}
          >
            <option value="">Select a subject</option>
            {subjects.map((subject, index) => (
              <option key={index} value={subject}>
                {subject}
              </option>
            ))}
          </select>
          <button
            onClick={startExam}
            className="start-exam-btn"
            disabled={!selectedSubject}
          >
            Start Exam
          </button>
        </>
      )}
    </div>
  );
};

export default ExamPage;
